#include <stdint.h>

uint64_t fixture(uint64_t s[4]) {
    uint64_t count = (s[0] & UINT64_C(7)) + UINT64_C(1);
    uint64_t total = s[1];
    uint64_t key = s[2];
    for (uint64_t i = 0; i < count; ++i) {
        uint64_t value = s[(i + key) & UINT64_C(3)];
        if ((value & UINT64_C(15)) == 0) {
            total ^= i;
            goto cleanup;
        }
        if ((value & UINT64_C(3)) == UINT64_C(1)) {
            s[3] += value;
            if ((s[3] & UINT64_C(7)) == 0)
                goto cleanup;
            continue;
        }
        total += value ^ (i + UINT64_C(1));
        s[1] = total;
    }
cleanup:
    s[1] = total;
    s[2] = key + (s[3] & UINT64_C(31));
    s[3] ^= total;
    return s[1] + s[2] + s[3];
}

