#include <stdint.h>

uint64_t fixture(uint64_t s[4]) {
    uint64_t gate = s[0] & UINT64_C(3);
    if (gate == 0)
        s[2] += s[1];
    else
        s[2] ^= s[3];
    uint64_t value = s[2];
    if (gate == 0) {
        if ((value & UINT64_C(1)) != 0)
            s[3] += value;
        else
            s[3] ^= value;
    } else {
        if ((value & UINT64_C(1)) != 0)
            s[3] ^= value;
        else
            s[3] += value;
    }
    if ((s[3] & UINT64_C(7)) == UINT64_C(3))
        return s[3] + value;
    s[1] = gate + value;
    return s[1] ^ s[3];
}

