#include <stdint.h>

uint64_t fixture(uint64_t s[4]) {
    uint64_t count = (s[0] & UINT64_C(7)) + UINT64_C(1);
    uint64_t tag = s[1];
    uint64_t total = s[2];
    for (uint64_t i = 0; i < count; ++i) {
        switch ((tag + i) & UINT64_C(3)) {
        case 0:
            total += s[3];
            /* fall through */
        case 1:
            tag ^= total + UINT64_C(1);
            break;
        case 2:
            total ^= s[(i + UINT64_C(1)) & UINT64_C(3)];
            if ((total & UINT64_C(7)) == 0)
                goto cleanup;
            break;
        default:
            tag += UINT64_C(3);
            continue;
        }
        s[2] = total;
        if ((tag & UINT64_C(15)) == UINT64_C(5))
            break;
    }
cleanup:
    s[1] = tag;
    s[2] = total;
    return tag + total;
}
